SELECT MAX(agreed_price) AS highest_earning
FROM nlq.my_deals
WHERE my_role = 'seller' AND status = 'completed';

SELECT COUNT(*) AS deactivated_accounts
FROM nlq.students
WHERE account_status = 'deactivated';

SELECT COUNT(*) AS moderator_count
FROM nlq.students
WHERE is_moderator = true;

SELECT COUNT(*) AS reviews_with_comment
FROM nlq.reviews
WHERE comment IS NOT NULL;

SELECT COUNT(*) AS self_removed_count
FROM nlq.listings_all
WHERE status = 'removed';

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (resolved_at - filed_at))/86400)::NUMERIC, 2) AS avg_days_to_resolve
FROM nlq.reports
WHERE status = 'resolved' AND resolved_at IS NOT NULL;

SELECT COUNT(*) AS listings_with_no_photos
FROM nlq.listings_all
WHERE photo_count = 0;
